// Zoom controller for the Sensor Telemetry Explorer.
//
// A gesture on a range slider hands the controller the control that was
// dragged and the new normalized window [startPct, endPct] the slider now
// shows. The controller decides how the scene's axes should look after the
// gesture: it moves the axes the gesture steers to the new window, and applies
// a policy to every other axis that the gesture does not steer.
import { fullWindow } from './axisScale.js';
import { resolveTargets } from './zoomBindings.js';

// Policy applied to an axis the current gesture does not steer.
//
//   'hold'  keep the axis window exactly as it was before the gesture
//   'reset' return the axis to its full extent
//
// The controller reads the policy from the scene; scenes that do not name one
// fall back to the historical behavior.
const DEFAULT_UNTOUCHED_POLICY = 'reset';

function untouchedWindow(policy, previousWindow) {
  if (policy === 'hold') return previousWindow.slice();
  return fullWindow();
}

// Apply a gesture and return the next per-axis window map, keyed by axis id.
//
// `windows` is the current window map (axis id -> [startPct, endPct]).
export function applyGesture(scene, controlId, gestureWindow, windows) {
  const control = scene.controls.find((c) => c.id === controlId);
  if (!control) return windows;
  const steered = new Set(resolveTargets(control, scene.axes));
  const policy = scene.untouchedPolicy || DEFAULT_UNTOUCHED_POLICY;
  const next = {};
  scene.axes.forEach((axis) => {
    if (steered.has(axis.id)) {
      next[axis.id] = gestureWindow.slice();
    } else {
      next[axis.id] = untouchedWindow(policy, windows[axis.id]);
    }
  });
  return next;
}
