// Continuous axis scale for the Sensor Telemetry Explorer.
//
// The chart draws two continuous axes. Each axis keeps a full data extent
// (the range the loaded series actually covers) and a current "window": the
// sub-interval of that extent the axis is currently showing. A window is a
// normalized pair [startPct, endPct] in [0, 1] over the axis extent, exactly
// the way a range slider reports its handle positions. Turning a window into
// concrete data values, and reading a window back off concrete values, both
// go through here so the same math is used everywhere.

// Clamp a raw percentage into [0, 1].
function clampPct(v) {
  if (v < 0) return 0;
  if (v > 1) return 1;
  return v;
}

// Given an axis extent [min, max] and a normalized window [startPct, endPct],
// return the concrete data interval [lo, hi] the window selects.
export function windowToValues(extent, window) {
  const [min, max] = extent;
  const span = max - min;
  const lo = min + span * clampPct(window[0]);
  const hi = min + span * clampPct(window[1]);
  return [lo, hi];
}

// Given an axis extent and a concrete data interval, return the normalized
// window [startPct, endPct] that would show exactly that interval.
export function valuesToWindow(extent, values) {
  const [min, max] = extent;
  const span = max - min || 1;
  return [clampPct((values[0] - min) / span), clampPct((values[1] - min) / span)];
}

// The full window: shows the entire extent.
export function fullWindow() {
  return [0, 1];
}

// Format a data value for the on-screen axis read-out. Values are rounded to
// one decimal so the read-out is stable to observe.
export function formatValue(v) {
  return (Math.round(v * 10) / 10).toFixed(1);
}
