:root {
  --bg: #0f1624;
  --panel: #16202f;
  --line: #2a3850;
  --ink: #dce6f5;
  --muted: #8394ad;
  --accent: #5cc8ff;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--ink);
}

.app-bar {
  display: flex;
  align-items: baseline;
  gap: 20px;
  padding: 14px 22px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}

.app-title { font-size: 17px; font-weight: 600; }
.scene { color: var(--muted); font-size: 13px; }
#scene-name { color: var(--accent); }

.workbench {
  display: grid;
  grid-template-columns: 1fr 260px;
  gap: 18px;
  padding: 20px 22px;
  align-items: start;
}

.chart-panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 16px;
}

.chart-holder { position: relative; }
#chart { display: block; width: 100%; height: auto; background: #0b1220; border-radius: 4px; }

.readouts {
  display: flex;
  gap: 26px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.axis-readout { font-size: 13px; }
.axis-name { color: var(--muted); margin-right: 8px; }
.axis-range { font-variant-numeric: tabular-nums; color: var(--ink); }

.controls-panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 16px;
}

.controls-heading { margin: 0 0 12px; font-size: 14px; font-weight: 600; }
.control-list { list-style: none; margin: 0; padding: 0; }
.control-row { margin-bottom: 16px; }
.control-label { display: block; font-size: 13px; color: var(--muted); margin-bottom: 6px; }
.zoom-slider { width: 100%; accent-color: var(--accent); }
.controls-hint { font-size: 12px; color: var(--muted); margin-top: 18px; line-height: 1.5; }
